import numpy as np

def alpha_bar(T, beta_start=1e-4, beta_end=0.02):
    return np.cumprod(1 - np.linspace(beta_start, beta_end, T))

def q_sample(x0, t, ab, eps):
    a = ab[t]
    return np.sqrt(a) * x0 + np.sqrt(1 - a) * eps
